package com.hbm.machine.exposurechamber;
import com.hbm.energy.*;
import com.hbm.item.battery.*;
import com.hbm.machine.electricfurnace.FurnaceUpgradeItem;
import com.hbm.machine.centrifuge.OverdriveUpgradeItem;
import com.hbm.machine.foundry.crucible.ThermalMachine;
import com.hbm.multiblock.DummyableBlock;
import com.hbm.world.structure.generated.compat.ForgeDirection;
import java.math.BigInteger;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
/** Actual eight-slot chamber. The source zero-count internal capsule is a private identity, never one collectible item. */
public final class ExposureChamberEntity extends ThermalMachine implements EnergyReceiver,SidedEnergyConnector {
 public static final BigInteger MAX_POWER=BigInteger.valueOf(1000000);public static final int MAX_PARTICLES=8;
 public BigInteger power=BigInteger.ZERO;public int progress,processTime=200,consumption=10000,savedParticles;public boolean isOn,tilted;public float rotation,prevRotation;
 private ItemStack particleIdentity=ItemStack.EMPTY;private final Map<BlockPos,PowerNode> powerNodes=new LinkedHashMap<>();private List<Port> activePorts=List.of();private CompoundTag lastSent;
 public ExposureChamberEntity(BlockPos pos,BlockState state){super(ExposureChamberContent.ENTITY.get(),pos,state,8);}
 @Override protected String title(){return "container.exposureChamber";}@Override public AbstractContainerMenu createMenu(int id,Inventory player,Player owner){return new ExposureChamberMenu(id,player,this,worldPosition);}@Override public void writeClientSideData(AbstractContainerMenu menu,net.minecraft.network.RegistryFriendlyByteBuf buffer){buffer.writeBlockPos(worldPosition);}
 public record Port(BlockPos position,Direction side){public NodeConnection connection(){return new NodeConnection(position.relative(side),side);}}
 public static List<Port> portDefinitions(BlockPos core,Direction facing){var dir=ForgeDirection.getOrientation(facing.get3DDataValue());var side=dir.getRotation(ForgeDirection.DOWN);var far7=core.offset(side.offsetX*7,0,side.offsetZ*7);var far8=core.offset(side.offsetX*8,0,side.offsetZ*8);return List.of(new Port(far7.relative(facing),facing),new Port(far7.relative(facing,-1),facing.getOpposite()),new Port(far8.relative(facing),facing),new Port(far8.relative(facing,-1),facing.getOpposite()),new Port(far8,side.nativeDirection()));}
 private void updatePorts(ServerLevel world){var now=portDefinitions(worldPosition,DummyableBlock.facing(getBlockState())).stream().filter(p->world.hasChunkAt(p.position)&&world.getBlockState(p.position).is(getBlockState().getBlock())&&DummyableBlock.isPort(world.getBlockState(p.position))).toList();if(!now.equals(activePorts)||powerNodes.values().stream().anyMatch(PowerNode::isExpired)){disconnect();activePorts=now;for(var port:now){var node=new PowerNode(port.position).setConnections(port.connection());HbmEnergy.nodespace(world).createNode(node);powerNodes.put(port.position,node);}}for(var node:powerNodes.values())if(node.hasValidNet())node.addReceiver(this);}
 public static void tick(Level level,BlockPos pos,BlockState state,ExposureChamberEntity self){if(level instanceof ServerLevel server)self.serverTick(server);else{self.prevRotation=self.rotation;if(self.isOn){self.rotation+=10;if(self.rotation>=720){self.rotation-=720;self.prevRotation-=720;}}}}
 public ExposureChamberRecipe getRecipe(ItemStack particle,ItemStack ingredient){if(level==null||particle.isEmpty()||ingredient.isEmpty())return null;for(var recipe:ExposureChamberRecipes.recipes(level.getRecipeManager()))if(recipe.inputItems().size()==2&&recipe.inputItems().get(0).matches(particle,true)&&recipe.inputItems().get(1).matches(ingredient,true))return recipe;return null;}
 private static boolean sameSource(ItemStack a,ItemStack b){return a.getItem()==b.getItem()&&com.hbm.material.HbmMaterials.metadata(a)==com.hbm.material.HbmMaterials.metadata(b);}
 private void upgrades(){int speed=0,efficient=0,overdrive=0;for(int i=6;i<=7;i++){var item=slots.get(i).getItem();if(item instanceof FurnaceUpgradeItem upgrade){if(upgrade.type()==FurnaceUpgradeItem.Type.SPEED)speed+=upgrade.tier();else efficient+=upgrade.tier();}else if(item instanceof OverdriveUpgradeItem upgrade)overdrive+=upgrade.tier();}speed=Math.min(3,speed);efficient=Math.min(3,efficient);overdrive=Math.min(3,overdrive);consumption=10000;processTime=200-200/4*speed;consumption*=speed/2+1;processTime*=efficient/2+1;consumption/=efficient+1;processTime/=overdrive+1;consumption*=overdrive*2+1;}
 private void charge(){if(power.signum()<0){power=BigInteger.ZERO;return;}if(power.compareTo(MAX_POWER)>0){power=MAX_POWER;return;}var stack=slots.get(5);if(stack.getItem() instanceof CreativeBatteryItem){power=MAX_POWER;return;}if(stack.getItem() instanceof HbmBattery battery){long amount=MAX_POWER.subtract(power).min(BigInteger.valueOf(battery.getDischargeRate(stack))).min(BigInteger.valueOf(battery.getCharge(stack))).longValueExact();battery.dischargeBattery(stack,amount);power=power.add(BigInteger.valueOf(amount));}}
 private void serverTick(ServerLevel world){updatePorts(world);isOn=false;charge();upgrades();if(particleIdentity.isEmpty()&&!slots.get(0).isEmpty()&&!slots.get(3).isEmpty()&&savedParticles<=0){var recipe=getRecipe(slots.get(0),slots.get(3));if(recipe!=null){var container=slots.get(0).getCraftingRemainingItem();boolean store=false;if(container.isEmpty())store=true;else if(slots.get(2).isEmpty()){slots.set(2,container.copy());store=true;}else if(sameSource(slots.get(2),container)&&slots.get(2).getCount()<slots.get(2).getMaxStackSize()){slots.get(2).grow(1);store=true;}if(store){particleIdentity=slots.get(0).copyWithCount(1);removeItem(0,1);savedParticles=MAX_PARTICLES;}}}
  if(!particleIdentity.isEmpty()&&savedParticles>0&&power.compareTo(BigInteger.valueOf(consumption))>=0){var recipe=getRecipe(particleIdentity,slots.get(3));var output=recipe==null?ItemStack.EMPTY:recipe.outputItems().getFirst().pool().getFirst().stack();if(recipe!=null&&(slots.get(4).isEmpty()||sameSource(slots.get(4),output)&&slots.get(4).getCount()+output.getCount()<=slots.get(4).getMaxStackSize())){progress++;power=power.subtract(BigInteger.valueOf(consumption));isOn=true;if(progress>=processTime){progress=0;savedParticles--;removeItem(3,1);if(slots.get(4).isEmpty())slots.set(4,output.copy());else slots.get(4).grow(output.getCount());}}else progress=0;}else progress=0;
  if(savedParticles<=0)particleIdentity=ItemStack.EMPTY;var tag=getUpdateTag(world.registryAccess());if(!tag.equals(lastSent)||world.getGameTime()%20==0){lastSent=tag;sync(50);}setChanged();
 }
 @Override public boolean canPlaceItem(int index,ItemStack stack){if(index==0&&!slots.get(0).isEmpty())return true;if(index==3&&!slots.get(3).isEmpty())return true;var particle=particleIdentity.isEmpty()?slots.get(0):particleIdentity;if(index==0&&particle.isEmpty()&&!slots.get(3).isEmpty())return getRecipe(stack,slots.get(3))!=null;if(index==3&&!particle.isEmpty()&&slots.get(3).isEmpty())return getRecipe(slots.get(0),stack)!=null; // Preserve original slot0-reference quirk while internal particles are cached.
  if(particle.isEmpty()&&slots.get(3).isEmpty()&&level!=null)for(var recipe:ExposureChamberRecipes.recipes(level.getRecipeManager())){if(index==0&&recipe.inputItems().get(0).matches(stack,true)||index==3&&recipe.inputItems().get(1).matches(stack,true))return true;}return false;}
 @Override public int[] getSlotsForFace(Direction side){return new int[]{0,2,3,4};}@Override public boolean canTakeItemThroughFace(int index,ItemStack stack,Direction side){return index==2||index==4;}
 @Override protected void saveMachine(CompoundTag tag){tag.putString("power",power.toString());tag.putInt("progress",progress);tag.putInt("savedParticles",savedParticles);tag.putInt("processTime",processTime);tag.putInt("consumption",consumption);tag.putBoolean("isOn",isOn);tag.putBoolean("tilted",tilted);}
 @Override protected void loadMachine(CompoundTag tag){power=tag.contains("power",8)?new BigInteger(tag.getString("power")):BigInteger.valueOf(tag.getLong("power"));progress=tag.getInt("progress");savedParticles=tag.getInt("savedParticles");if(tag.contains("processTime"))processTime=tag.getInt("processTime");if(tag.contains("consumption"))consumption=tag.getInt("consumption");isOn=tag.getBoolean("isOn");tilted=tag.getBoolean("tilted");}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.remove("processTime");tag.remove("consumption");tag.remove("isOn");if(tag.contains("CustomName"))tag.putString("name",getDisplayName().getString());if(!particleIdentity.isEmpty())tag.put("hbmParticleIdentity",particleIdentity.copyWithCount(1).save(lookup));}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);if(!tag.contains("CustomName")&&tag.contains("name",Tag.TAG_STRING)&&!tag.getString("name").isEmpty())setCustomName(net.minecraft.network.chat.Component.literal(tag.getString("name")));particleIdentity=tag.contains("hbmParticleIdentity",Tag.TAG_COMPOUND)?ItemStack.parseOptional(lookup,tag.getCompound("hbmParticleIdentity")):slots.get(1).copy();if(!particleIdentity.isEmpty())particleIdentity.setCount(1);slots.set(1,ItemStack.EMPTY);}
 private static long legacy(BigInteger value){return value.max(BigInteger.valueOf(Long.MIN_VALUE)).min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}@Override public long getPower(){return legacy(power);}@Override public long getMaxPower(){return 1000000;}@Override public void setPower(long value){setPowerExact(BigInteger.valueOf(value));}@Override public BigInteger getPowerExact(){return power;}@Override public BigInteger getMaxPowerExact(){return MAX_POWER;}@Override public void setPowerExact(BigInteger value){power=value;setChanged();}@Override public BigInteger getReceiverSpeedExact(){return MAX_POWER;}@Override public long transferPower(long amount){return transferPowerExact(BigInteger.valueOf(amount)).longValueExact();}@Override public BigInteger transferPowerExact(BigInteger amount){if(amount.signum()<0)throw new IllegalArgumentException("Negative HE transfer");var room=MAX_POWER.subtract(power);if(room.signum()<0)throw new IllegalStateException("Invalid source chamber HE");var accepted=room.min(amount);power=power.add(accepted);if(accepted.signum()!=0)setChanged();return amount.subtract(accepted);}@Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null;}@Override public long energyStored(){return getPower();}@Override public long energyCapacity(){return 1000000;}@Override public List<ProgressView> progressBars(){return List.of(new ProgressView("gui.hbm.exposure.progress",progress,processTime+1,0x71c78b),new ProgressView("gui.hbm.exposure.particles",savedParticles,MAX_PARTICLES,0x80d0ff));}
 private void disconnect(){if(level instanceof ServerLevel world)for(var node:powerNodes.values())HbmEnergy.nodespace(world).destroyNode(node);powerNodes.clear();activePorts=List.of();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}@Override public void setRemoved(){disconnect();super.setRemoved();}
}
